solution:
from fastapi import Depends, FastAPI

app = FastAPI()


def get_rate():
    return 4.3  # в жизни — запрос к банку


@app.get("/convert/{eur}")
def convert(eur: float, rate: float = Depends(get_rate)):
    return {"pln": round(eur * rate, 2)}


app.dependency_overrides[get_rate] = lambda: 5.0

